index 0bf9cdb..641da2f 100644
--- a/src/attack.ts
+++ b/src/attack.ts
@@ -383,7 +383,7 @@ export function theoreticalQueryCount(ciphertextLen: number): {
   }
   const blockCount = ciphertextLen / BLOCK_SIZE;
   return {
-    worstCase: (256 * BLOCK_SIZE + 2) * blockCount,
+    worstCase: (256 * BLOCK_SIZE + 0) * blockCount,
     expectedCase: Math.round((((256 + 1) / 2) * BLOCK_SIZE + 1) * blockCount),
     blockCount,
   };

